      f.os +
      '&gpu=' +
      die +
      (mode === 'live' && f.cpu !== 'any' ? '&cpu=' + f.cpu : '') +
      (mode === 'live' && f.driver ? '&driver=' + f.driver : '') +
      (f.tier ? '&tier=' + f.tier : '') +
      (wanted.includes('community') ? '&source=' + wanted.join(',') : '')
