    q.set('os', f.os);
    if (f.host_driver) q.set('host_driver', f.host_driver);
    if (f.guest_driver) q.set('guest_driver', f.guest_driver);
    if (f.cpu !== 'any') q.set('cpu', f.cpu);
    if (f.relaxGiven) q.set('relax', f.relax.length ? f.relax.join(',') : 'none');
