      ended_at: text(raw.ended_at),
      perf: arr(raw.perf).filter(
        (r) => isObj(r) && text(r.name) && finite(r.value) !== null && !/spec\s*view/i.test(text(r.name) + ' ' + text(r.suite)),
      ),
